-- 0018 · Finance and insurance through licensed partners (spec 24.8). Additive only.
-- Service groups for every finance and insurance category in PLATFORM_VISION §7–8, with request questions.
-- While these verticals are "coming soon" nobody can request them; when AB switches one live, requests
-- go through the request engine to partner organisations (kinds lender, insurer, broker from 0012).

insert into public.service_categories (name, slug, description, icon, sort, vertical_key, is_active)
values
  ('Finance', 'finance', 'Property and construction finance through approved, licensed partners.', 'landmark', 70, 'finance', true),
  ('Insurance', 'insurance', 'Property and construction insurance through approved, licensed partners.', 'shield-check', 80, 'insurance', true)
on conflict (slug) do nothing;

